-- Generated by fivem-tools.com - postal helper for this custom minimap.
-- Loads the bundled postals.json (GTA world coords), adds a /gps command
-- that drops the pause-map waypoint, and exposes a GetPostalCoords export.

local Postals = {}

do
    local raw = LoadResourceFile(GetCurrentResourceName(), 'postals.json')
    if raw then
        local ok, decoded = pcall(json.decode, raw)
        if ok and type(decoded) == "table" then
            Postals = decoded
        else
            print('^1[gps] failed to parse postals.json^0')
        end
    else
        print('^1[gps] postals.json not found^0')
    end
end

-- Look up a postal code; accepts a number or string. Returns x, y or nil.
local function lookup(postal)
    if postal == nil then return nil end
    local p = Postals[tostring(postal)]
    if not p then return nil end
    return p.x + 0.0, p.y + 0.0
end

-- Export: GetPostalCoords(postal) -> vector3(x, y, 0.0) (0.0 = no stored Z).
-- Call it from any resource: exports[GetCurrentResourceName()]:GetPostalCoords('2003')
exports("GetPostalCoords", function(postal)
    local x, y = lookup(postal)
    if not x then return nil end
    return vector3(x, y, 0.0)
end)

-- Client only: the chat command that sets the pause-menu map waypoint.
if not IsDuplicityVersion() then
    RegisterCommand('gps', function(_, args)
        local postal = args[1]
        if not postal then
            TriggerEvent('chat:addMessage', { args = { '^3[gps]', 'Usage: /gps <postal>' } })
            return
        end
        local x, y = lookup(postal)
        if not x then
            TriggerEvent('chat:addMessage', { args = { '^1[gps]', ('Unknown postal: %s'):format(tostring(postal)) } })
            return
        end
        SetNewWaypoint(x, y)
        TriggerEvent('chat:addMessage', { args = { '^2[gps]', ('Waypoint set to postal %s'):format(tostring(postal)) } })
    end, false)
end
